/**
 * One mark as inline SVG.
 *
 * @param string $slug  Mark slug.
 * @param bool   $color Draw in the brand colour (true) or currentColor.
 * @return string
 */
function raze_mark( $slug, $color = true ) {
	$marks = raze_marks();
	if ( ! isset( $marks[ $slug ] ) ) {
		return '';
	}
	$m = $marks[ $slug ];
	return sprintf(
		'<svg class="mark mark-%1$s" viewBox="0 0 24 24" width="24" height="24" aria-hidden="true" focusable="false"><path fill="%2$s" d="%3$s"/></svg>',
		esc_attr( $slug ),
		$color ? esc_attr( $m['color'] ) : 'currentColor',
		esc_attr( $m['path'] )
	);
}
